const raw = $json;
const value = (raw.messages ? raw : (raw.body && raw.body.entry && raw.body.entry[0] && raw.body.entry[0].changes && raw.body.entry[0].changes[0] && raw.body.entry[0].changes[0].value)) || raw;
const msg = (value.messages && value.messages[0]) || {};
const tipoMensagem = msg.type || 'desconhecido';
let texto = '';
let respostaId = '';
if (tipoMensagem === 'text') {
  texto = (msg.text && msg.text.body) || '';
} else if (tipoMensagem === 'interactive') {
  if (msg.interactive && msg.interactive.type === 'button_reply') {
    respostaId = (msg.interactive.button_reply && msg.interactive.button_reply.id) || '';
    texto = (msg.interactive.button_reply && msg.interactive.button_reply.title) || '';
  } else if (msg.interactive && msg.interactive.type === 'list_reply') {
    respostaId = (msg.interactive.list_reply && msg.interactive.list_reply.id) || '';
    texto = (msg.interactive.list_reply && msg.interactive.list_reply.title) || '';
  }
} else if (tipoMensagem === 'button') {
  respostaId = (msg.button && msg.button.payload) || '';
  texto = (msg.button && msg.button.text) || '';
}
const lat = (msg.location && msg.location.latitude != null) ? msg.location.latitude : null;
const long = (msg.location && msg.location.longitude != null) ? msg.location.longitude : null;
const mediaId = (msg.image && msg.image.id) || (msg.audio && msg.audio.id) || null;
const fromRaw = msg.from || '';
const telefone = fromRaw.indexOf('+') === 0 ? fromRaw : ('+' + fromRaw);
const textoNormalizado = texto.trim();
const matchContrato = textoNormalizado.match(/^contrato\s+(\S+)\s+assinado$/i);
const matchMaquininha = textoNormalizado.match(/^maquininha\s+(\S+)\s+ativada$/i);
let comandoTipo = '';
let comandoCodcl = '';
if (matchContrato) {
  comandoTipo = 'contrato_assinado';
  comandoCodcl = matchContrato[1];
} else if (matchMaquininha) {
  comandoTipo = 'maquininha_ativada';
  comandoCodcl = matchMaquininha[1];
}
return {
  json: {
    telefone: telefone,
    tipoMensagem: tipoMensagem,
    texto: textoNormalizado,
    respostaId: respostaId,
    lat: lat,
    long: long,
    mediaId: mediaId,
    waMessageId: msg.id || null,
    comandoTipo: comandoTipo,
    comandoCodcl: comandoCodcl
  }
};

