if (!Array.isArray(rows) || rows.length === 0) return [];
const loja = rows[0];
const ctx = $('Validar Usuario Ativo').first().json;
return [{ json: Object.assign({}, ctx, { lojaId: loja.id, lojaNome: loja.nome }) }];

const items = $input.all();
const rows = (items.length ? items[0].json : []) || [];
if (!Array.isArray(rows) || rows.length === 0) return [];
const contrato = rows[0];
const ctx = $('Extrair Loja Contrato Assinado').first().json;
