const items = $input.all();
const rows = (items.length ? items[0].json : []) || [];
if (!Array.isArray(rows) || rows.length === 0) return [];
const contrato = rows[0];
const ctx = $('Extrair Loja Maquininha').first().json;
const vigenciaInicio = $today.plus({ months: 1 }).startOf('month').toISODate();
const patchBody = { etapa: 'ativo', data_ativacao: $today.toISODate() };
if (contrato.produto === 'top_service') {
