}
return [{ json: Object.assign({}, ctx, { contratoId: contrato.id, produtoContrato: contrato.produto, patchBody: patchBody }) }];

const items = $input.all();
const rows = (items.length ? items[0].json : []) || [];
const found = (Array.isArray(rows) && rows.length) ? rows[0] : null;
const usuario = $('Validar Usuario Ativo').first().json;
const estado = found ? found.estado : 'ocioso';
const contexto = (found && found.contexto) ? found.contexto : {};
return [{
  json: Object.assign({}, usuario, {
