const items = $input.all();
const rows = (items.length ? items[0].json : []) || [];
const ctx = $('Normalizar Estado').first().json;
if (!Array.isArray(rows) || rows.length === 0) {
  return [{ json: Object.assign({}, ctx, { nenhumaVisitaPendente: 'true' }) }];
}
const lat1 = parseFloat(ctx.lat);
const lon1 = parseFloat(ctx.long);
function toRad(v) { return (v * Math.PI) / 180; }
function haversine(la1, lo1, la2, lo2) {
  const R = 6371000;
  const dLat = toRad(la2 - la1);
  const dLon = toRad(lo2 - lo1);
  const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(toRad(la1)) * Math.cos(toRad(la2)) *
    Math.sin(dLon / 2) * Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
}
let melhor = null;
let melhorDist = Infinity;
for (const row of rows) {
  const loja = row.lojas || {};
  if (loja.lat == null || loja.long == null) continue;
  const d = haversine(lat1, lon1, parseFloat(loja.lat), parseFloat(loja.long));
  if (d < melhorDist) {
    melhorDist = d;
    melhor = { agendaId: row.id, lojaId: loja.id, lojaNome: loja.nome };
  }
}
if (!melhor) {
  return [{ json: Object.assign({}, ctx, { nenhumaVisitaPendente: 'true' }) }];
}
return [{
  json: Object.assign({}, ctx, {
    nenhumaVisitaPendente: 'false',
    agendaId: melhor.agendaId,
    lojaId: melhor.lojaId,
    lojaNome: melhor.lojaNome,
    distanciaM: Math.round(melhorDist),
    checkinLat: lat1,
    checkinLong: lon1
  })
}];

const items = $input.all();
const rows = (items.length ? items[0].json : []) || [];
const ctx = $('Calcular Loja Mais Proxima').first().json;
const raio = rows.length ? parseFloat(rows[0].valor) : 200;
const flagSuspeito = ctx.distanciaM > raio ? 'true' : 'false';
return [{
  json: Object.assign({}, ctx, {
    raioCheckinM: raio,
    flagSuspeito: flagSuspeito
  })
}];

const items = $input.all();
const rows = (items.length ? items[0].json : []) || [];
const ctx = $('Avaliar Suspeita').first().json;
const papelUsuario = $('Validar Usuario Ativo').first().json.papel;
// Escalonamento (D-06): check-in suspeito do proprio coordenador sobe ao gerente.
const papelDestino = papelUsuario === 'coordenador' ? 'gerente' : 'coordenador';
const destinatarios = rows.filter((u) => u.papel === papelDestino && u.telegram_chat_id);
return destinatarios.map((c) => ({
  json: {
    destinatarioChatId: c.telegram_chat_id,
    destinatarioTelefone: c.telefone,
    destinatarioPapel: c.papel,
