  }
}));

const ctx = $('Normalizar Estado').first().json;
const contexto = ctx.contexto || {};
const agendaId = contexto.agenda_id;
const fotoUrl = 'rotaviva-fotos/' + agendaId + '.jpg';
return [{ json: Object.assign({}, ctx, { fotoUrl: fotoUrl }) }];

const items = $input.all();
const rows = (items.length ? items[0].json : []) || [];
const visita = Array.isArray(rows) ? rows[0] : rows;
const ctx = $('Preparar Contexto Apos Upload').first().json;
return [{ json: Object.assign({}, ctx, { visitaId: visita.id }) }];

const ctx = $('Normalizar Estado').first().json;
const transcricao = $('Transcrever Audio').first().json;
const estruturado = ($input.first().json && $input.first().json.output) || {};
return [{ json: Object.assign({}, ctx, {
  obsAudioTranscrito: (transcricao && transcricao.text) || '',
  motivoEstruturado: estruturado.motivo || null,
  contrapropostaEstruturada: estruturado.contraproposta || null,
  dataRetornoSugeridaEstruturada: estruturado.data_retorno_sugerida || null,
  resumoEstruturado: estruturado.resumo || null
}) }];

const item = $json;
const contexto = item.contexto || {};
const etapaAtual = contexto.etapa_checkout || null;
const respostaId = item.respostaId || '';
const textoResp = (item.texto || '').trim();
const tipoMensagem = item.tipoMensagem;
const usuarioId = item.usuarioId;
const telefone = item.telefone;
const visitaId = contexto.visita_id;
const agendaId = contexto.agenda_id;
const lojaId = contexto.loja_id;

const hoje = $today.toISODate();

function proximoDiaUtil() {
  let d = $today.plus({ days: 1 });
  while (d.weekday === 6 || d.weekday === 7) {
    d = d.plus({ days: 1 });
  }
  return d.toISODate();
}

let novoEstado = 'checkout';
let novoContexto = Object.assign({}, contexto);
let visitaUpdates = {};
let temVisitaUpdates = 'false';
let acaoEspecial = 'nenhuma';
let dadosAgendaReagendada = null;
let dadosOportunidade = null;
let dadosContrato = null;
let marcarAgendaRealizada = 'false';
let mensagemSaida = { tipo: 'text', texto: 'Nao entendi sua resposta. Pode tentar novamente?', opcoes: [] };

function listaProduto() {
  return {
    tipo: 'list',
    texto: 'Interesse em qual produto?',
    opcoes: [
      { id: 'produto_autocred', titulo: 'Autocred' },
      { id: 'produto_top_service', titulo: 'Top Service' },
      { id: 'produto_ambos', titulo: 'Ambos' },
      { id: 'produto_nenhum', titulo: 'Nenhum' }
    ]
  };
}
function botoesFecharAnalisar() {
  return {
    tipo: 'buttons',
    texto: 'Fechou ou vai analisar?',
    opcoes: [
      { id: 'fa_fechou', titulo: 'Fechou' },
      { id: 'fa_analisar', titulo: 'Analisar' }
    ]
  };
}
function listaDataRetorno() {
  return {
    tipo: 'list',
    texto: 'Qual a data de retorno prevista?',
    opcoes: [
      { id: 'dr_amanha', titulo: 'Amanha' },
      { id: 'dr_3dias', titulo: '3 dias' },
      { id: 'dr_prox_semana', titulo: 'Proxima semana' },
      { id: 'dr_outra', titulo: 'Outra data' }
    ]
  };
}
function listaMotivo() {
  return {
    tipo: 'list',
    texto: 'Qual o motivo?',
    opcoes: [
      { id: 'motivo_taxas', titulo: 'Taxas concorrente' },
      { id: 'motivo_ja_possui', titulo: 'Ja possui' },
      { id: 'motivo_decisor_ausente', titulo: 'Decisor ausente' },
      { id: 'motivo_outro', titulo: 'Outro' }
    ]
  };
}
function botoesContraproposta() {
  return {
    tipo: 'buttons',
    texto: 'Houve contraproposta?',
    opcoes: [
      { id: 'cp_sim', titulo: 'Sim' },
      { id: 'cp_nao', titulo: 'Nao' }
    ]
  };
}
function textoObservacao(prefixo) {
  return {
    tipo: 'text',
    texto: (prefixo ? prefixo + '\n\n' : '') + 'Alguma observacao sobre a visita? (texto, audio, ou responda nao)',
    opcoes: []
  };
}

if (etapaAtual === 'decisor') {
  if (['decisor_sim', 'decisor_nao', 'decisor_loja_fechada', 'decisor_contato_ausente'].indexOf(respostaId) === -1) {
    mensagemSaida = {
      tipo: 'list',
      texto: 'Nao entendi. Falou com o decisor da loja?',
      opcoes: [
        { id: 'decisor_sim', titulo: 'Sim' },
        { id: 'decisor_nao', titulo: 'Nao' },
        { id: 'decisor_loja_fechada', titulo: 'Loja fechada' },
        { id: 'decisor_contato_ausente', titulo: 'Contato ausente' }
      ]
    };
  } else if (respostaId === 'decisor_loja_fechada' || respostaId === 'decisor_contato_ausente') {
    visitaUpdates = {
      resultado: respostaId === 'decisor_loja_fechada' ? 'loja_fechada' : 'contato_ausente',
      checkout_at: $now.toISO()
    };
    temVisitaUpdates = 'true';
    marcarAgendaRealizada = 'true';
    acaoEspecial = 'reagendar';
    dadosAgendaReagendada = { data: proximoDiaUtil(), usuario_id: usuarioId, loja_id: lojaId, origem: 'reagendada', status: 'pendente' };
    novoEstado = 'ocioso';
    novoContexto = {};
    mensagemSaida = { tipo: 'text', texto: 'Visita encerrada. Obrigado! Reagendei essa loja para o proximo dia util.', opcoes: [] };
  } else {
    visitaUpdates = { falou_decisor: respostaId === 'decisor_sim', resultado: 'normal' };
    temVisitaUpdates = 'true';
    novoContexto = Object.assign({}, contexto, { etapa_checkout: 'produto' });
    mensagemSaida = listaProduto();
  }
} else if (etapaAtual === 'produto') {
  const mapaProduto = { produto_autocred: 'autocred', produto_top_service: 'top_service', produto_ambos: 'ambos', produto_nenhum: 'nenhum' };
  if (!mapaProduto[respostaId]) {
    mensagemSaida = listaProduto();
  } else {
    visitaUpdates = { produto_interesse: mapaProduto[respostaId] };
    temVisitaUpdates = 'true';
    if (respostaId === 'produto_nenhum') {
      novoContexto = Object.assign({}, contexto, { etapa_checkout: 'motivo' });
      mensagemSaida = listaMotivo();
    } else {
      novoContexto = Object.assign({}, contexto, { etapa_checkout: 'fechou_ou_analisar', produto_selecionado: mapaProduto[respostaId] });
      mensagemSaida = botoesFecharAnalisar();
    }
  }
} else if (etapaAtual === 'fechou_ou_analisar') {
  if (respostaId === 'fa_fechou') {
    visitaUpdates = { status_1: 'fechou' };
    temVisitaUpdates = 'true';
    acaoEspecial = 'oportunidade';
    dadosOportunidade = { visita_id: visitaId, loja_id: lojaId, produto: contexto.produto_selecionado, status: 'aberta' };
    dadosContrato = { loja_id: lojaId, produto: contexto.produto_selecionado, etapa: 'docs_enviados', etapa_desde: hoje };
    novoContexto = Object.assign({}, contexto, { etapa_checkout: 'observacao' });
    mensagemSaida = textoObservacao('Registrado! Envie a documentacao a matriz e me avise quando o cliente assinar.');
  } else if (respostaId === 'fa_analisar') {
    novoContexto = Object.assign({}, contexto, { etapa_checkout: 'data_retorno' });
    mensagemSaida = listaDataRetorno();
  } else {
    mensagemSaida = botoesFecharAnalisar();
  }
} else if (etapaAtual === 'data_retorno') {
  const mapaData = { dr_amanha: 1, dr_3dias: 3, dr_prox_semana: 7 };
  if (respostaId === 'dr_outra') {
    novoContexto = Object.assign({}, contexto, { etapa_checkout: 'data_retorno_outra' });
    mensagemSaida = { tipo: 'text', texto: 'Informe a data de retorno (dd/mm/aaaa):', opcoes: [] };
  } else if (mapaData[respostaId]) {
    const dataRetorno = $today.plus({ days: mapaData[respostaId] }).toISODate();
    visitaUpdates = { status_1: 'analisar', data_retorno: dataRetorno };
    temVisitaUpdates = 'true';
    novoContexto = Object.assign({}, contexto, { etapa_checkout: 'observacao' });
    mensagemSaida = textoObservacao('Combinado, retorno agendado para ' + dataRetorno + '.');
  } else {
    mensagemSaida = listaDataRetorno();
  }
} else if (etapaAtual === 'data_retorno_outra') {
  if (!textoResp) {
    mensagemSaida = { tipo: 'text', texto: 'Nao entendi. Informe a data de retorno (dd/mm/aaaa):', opcoes: [] };
  } else {
    visitaUpdates = { status_1: 'analisar', data_retorno: textoResp };
    temVisitaUpdates = 'true';
    novoContexto = Object.assign({}, contexto, { etapa_checkout: 'observacao' });
    mensagemSaida = textoObservacao('Combinado, retorno agendado para ' + textoResp + '.');
  }
} else if (etapaAtual === 'motivo') {
  const mapaMotivo = { motivo_taxas: 'Taxas concorrente', motivo_ja_possui: 'Ja possui', motivo_decisor_ausente: 'Decisor ausente', motivo_outro: 'Outro' };
  if (!mapaMotivo[respostaId]) {
    mensagemSaida = listaMotivo();
  } else {
    novoContexto = Object.assign({}, contexto, { etapa_checkout: 'contraproposta', motivo_selecionado: mapaMotivo[respostaId] });
    mensagemSaida = botoesContraproposta();
  }
} else if (etapaAtual === 'contraproposta') {
  if (respostaId !== 'cp_sim' && respostaId !== 'cp_nao') {
    mensagemSaida = botoesContraproposta();
  } else {
    visitaUpdates = {
      status_1: 'sem_interesse',
      motivo_nao_fechamento: contexto.motivo_selecionado,
      contraproposta: respostaId === 'cp_sim' ? 'Sim' : 'Nao'
    };
    temVisitaUpdates = 'true';
    novoContexto = Object.assign({}, contexto, { etapa_checkout: 'observacao' });
    mensagemSaida = textoObservacao('Entendido.');
  }
} else if (etapaAtual === 'observacao') {
  const updates = { checkout_at: $now.toISO() };
  if (tipoMensagem === 'audio') {
    updates.obs_audio_transcrito = item.obsAudioTranscrito || '';
    if (item.motivoEstruturado) updates.motivo_nao_fechamento = item.motivoEstruturado;
    if (item.contrapropostaEstruturada) updates.contraproposta = item.contrapropostaEstruturada;
    if (item.dataRetornoSugeridaEstruturada) updates.data_retorno = item.dataRetornoSugeridaEstruturada;
  } else {
    const textoLower = textoResp.toLowerCase();
    const textoSemAcento = textoLower.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    if (textoSemAcento !== 'nao') {
      updates.obs_texto = textoResp;
    }
  }
  visitaUpdates = updates;
  temVisitaUpdates = 'true';
  marcarAgendaRealizada = 'true';
  novoEstado = 'ocioso';
  novoContexto = {};
  mensagemSaida = { tipo: 'text', texto: 'Obrigado! Visita concluida com sucesso.', opcoes: [] };
} else {
  novoEstado = 'ocioso';
  novoContexto = {};
  mensagemSaida = { tipo: 'text', texto: 'Ocorreu um erro no fluxo de checkout. Por favor, envie sua localizacao para reiniciar o check-in.', opcoes: [] };
}

return {
  json: {
    telefone: telefone,
    novoEstado: novoEstado,
    novoContexto: novoContexto,
    visitaId: visitaId,
    agendaIdParaRealizar: agendaId,
    visitaUpdates: visitaUpdates,
    temVisitaUpdates: temVisitaUpdates,
    acaoEspecial: acaoEspecial,
    dadosAgendaReagendada: dadosAgendaReagendada,
    dadosOportunidade: dadosOportunidade,
    dadosContrato: dadosContrato,
    marcarAgendaRealizada: marcarAgendaRealizada,
    mensagemSaida: mensagemSaida
  }
};

const ctx = $input.first().json;
return [{ json: Object.assign({}, ctx, {
  obsAudioTranscrito: null,
  motivoEstruturado: null,
  contrapropostaEstruturada: null,
  dataRetornoSugeridaEstruturada: null,
  resumoEstruturado: null
}) }];

const u = $json;
const cq = u.callback_query || null;
const msg = cq ? (cq.message || {}) : (u.message || u.edited_message || {});
const chatId = String((cq ? (cq.from && cq.from.id) : (msg.chat && msg.chat.id)) || (msg.chat && msg.chat.id) || '');
let tipoMensagem = 'desconhecido';
let texto = '';
let respostaId = '';
let lat = null, long = null, mediaId = null, contactPhone = '';
let isStart = false;
if (cq) {
  tipoMensagem = 'interactive';
  respostaId = cq.data || '';
} else if (u.message) {
  const m = u.message;
  if (m.text != null) {
    texto = String(m.text).trim();
    tipoMensagem = 'text';
    if (texto.toLowerCase() === '/start') isStart = true;
  } else if (m.location) {
    tipoMensagem = 'location'; lat = m.location.latitude; long = m.location.longitude;
  } else if (m.photo && m.photo.length) {
    tipoMensagem = 'image'; mediaId = m.photo[m.photo.length - 1].file_id;
  } else if (m.voice) {
    tipoMensagem = 'audio'; mediaId = m.voice.file_id;
  } else if (m.audio) {
    tipoMensagem = 'audio'; mediaId = m.audio.file_id;
  } else if (m.contact) {
    tipoMensagem = 'contact'; contactPhone = m.contact.phone_number || '';
  }
}
const mC = texto.match(/^contrato\s+(\S+)\s+assinado$/i);
const mM = texto.match(/^maquininha\s+(\S+)\s+ativada$/i);
let comandoTipo = '', comandoCodcl = '';
if (mC) { comandoTipo = 'contrato_assinado'; comandoCodcl = mC[1]; }
else if (mM) { comandoTipo = 'maquininha_ativada'; comandoCodcl = mM[1]; }
const SUPA = 'https://zvqwjtndvbqryonjplal.supabase.co/rest/v1';
const urlUsuario = SUPA + '/usuarios?telegram_chat_id=eq.' + encodeURIComponent(chatId) + '&ativo=eq.true&select=*';
return { json: { canal: 'telegram', identidade: 'tg:' + chatId, chatId, telefone: '', tipoMensagem, texto, respostaId, lat, long, mediaId, waMessageId: null, comandoTipo, comandoCodcl, contactPhone, isStart, callbackQueryId: cq ? cq.id : '', urlUsuario } };

const ctx = $('Normalizar Telegram').first().json;
const chatId = ctx.chatId;
function canon(s){ let d = String(s || '').replace(/\D/g, ''); if (d.startsWith('55') && d.length > 11) d = d.slice(2); if (d.length === 11) d = d.slice(0, 2) + d.slice(3); return d; }
const alvo = canon(ctx.contactPhone);
const users = $input.all().map(i => i.json);
let found = null;
for (const usr of users) { if (alvo && canon(usr.telefone) === alvo) { found = usr; break; } }
if (found) return [{ json: { match: true, usuarioId: found.id, nome: found.nome, chatId } }];
return [{ json: { match: false, chatId } }];

const j = $json;
if (!j.urlUsuario) {
  const SUPA = 'https://zvqwjtndvbqryonjplal.supabase.co/rest/v1';
  j.canal = j.canal || 'whatsapp';
  j.chatId = j.chatId || '';
  j.isStart = j.isStart || false;
  j.contactPhone = j.contactPhone || '';
  j.urlUsuario = SUPA + '/usuarios?telefone=eq.' + encodeURIComponent(j.telefone || '') + '&ativo=eq.true&select=*';
}
return { json: j };
